import { useEffect, useRef, useState } from 'react';
import styled from '@emotion/styled';
import { theme } from '@atlantis/shared';

const Wrapper = styled.div`
  background: ${theme.colors.codeBg};
  border: 1px solid ${theme.colors.codeBorder};
  border-radius: ${theme.borderRadius.md};
  padding: ${theme.spacing.lg};
  margin: ${theme.spacing.lg} 0;
  overflow-x: auto;
  text-align: center;

  svg {
    max-width: 100%;
  }
`;

const ErrorBox = styled.div`
  color: #f85149;
  font-family: ${theme.typography.fontFamilyMono};
  font-size: ${theme.typography.fontSizeSm};
  white-space: pre-wrap;
`;

interface MermaidBlockProps {
  code: string;
}

let mermaidInitialized = false;

export function MermaidBlock({ code }: MermaidBlockProps) {
  const ref = useRef<HTMLDivElement>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setError(null);

    async function render() {
      const mermaid = (await import('mermaid')).default;

      if (!mermaidInitialized) {
        mermaid.initialize({
          startOnLoad: false,
          theme: 'dark',
          themeVariables: {
            background: theme.colors.codeBg,
            primaryColor: theme.colors.accent,
            primaryTextColor: theme.colors.mainText,
            lineColor: theme.colors.border,
          },
        });
        mermaidInitialized = true;
      }

      if (!ref.current || cancelled) return;

      try {
        const id = `mermaid-${Math.random().toString(36).slice(2)}`;
        const { svg } = await mermaid.render(id, code);
        if (!cancelled && ref.current) {
          ref.current.innerHTML = svg;
        }
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : String(err));
        }
      }
    }

    render();
    return () => { cancelled = true; };
  }, [code]);

  if (error) {
    return (
      <Wrapper>
        <ErrorBox>Mermaid error: {error}</ErrorBox>
      </Wrapper>
    );
  }

  return <Wrapper ref={ref} />;
}
